import{_ as e,o as a,c as i,a0 as l}from"./chunks/framework.DQOulFGV.js";const s="data:image/svg+xml;base64,",p=JSON.parse('{"title":"第3章 集群模式","description":"","frontmatter":{},"headers":[],"relativePath":"redis/04-high-availability/chapter-03-cluster.md","filePath":"redis/04-high-availability/chapter-03-cluster.md"}'),I={name:"redis/04-high-availability/chapter-03-cluster.md"};function d(n,t,g,h,o,r){return a(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="第3章-集群模式" tabindex="-1">第3章 集群模式 <a class="header-anchor" href="#第3章-集群模式" aria-label="Permalink to &quot;第3章 集群模式&quot;">​</a></h1><blockquote><p>哨兵解决了高可用，但数据量大到单机装不下时，就需要把数据分片到多个节点。Redis Cluster 通过哈希槽把数据分散到多个主节点，同时支持水平扩展与自动故障转移。本章讲解集群的分片原理、请求路由与选型。</p></blockquote><hr><h2 id="_3-1-分片原理" tabindex="-1">3.1 分片原理 <a class="header-anchor" href="#_3-1-分片原理" aria-label="Permalink to &quot;3.1 分片原理&quot;">​</a></h2><p>Redis Cluster 把整个键空间划分为 <strong>16384 个哈希槽（slot）</strong>，每个节点负责一部分槽，数据按 key 映射到槽。</p><h3 id="槽的分配" tabindex="-1">槽的分配 <a class="header-anchor" href="#槽的分配" aria-label="Permalink to &quot;槽的分配&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>节点 A：负责 slot 0 ~ 5460</span></span>
<span class="line"><span>节点 B：负责 slot 5461 ~ 10922</span></span>
<span class="line"><span>节点 C：负责 slot 10923 ~ 16383</span></span></code></pre></div><h3 id="key-到槽的映射" tabindex="-1">key 到槽的映射 <a class="header-anchor" href="#key-到槽的映射" aria-label="Permalink to &quot;key 到槽的映射&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>槽号 = CRC16(key) % 16384</span></span></code></pre></div><ul><li>对 key 计算 CRC16 校验和，再对 16384 取模</li><li>得到 0~16383 范围内的槽号</li></ul><h3 id="为什么是-16384" tabindex="-1">为什么是 16384 <a class="header-anchor" href="#为什么是-16384" aria-label="Permalink to &quot;为什么是 16384&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">原因</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">心跳包大小</td><td style="text-align:left;">节点间 Gossip 心跳携带槽信息，16384 个槽刚好用 2KB 表示</td></tr><tr><td style="text-align:left;">节点数上限</td><td style="text-align:left;">官方建议节点数 ~1000，16384 个槽足够分配</td></tr><tr><td style="text-align:left;">网络开销</td><td style="text-align:left;">槽数量过大时心跳包更大，节点通信开销增加</td></tr></tbody></table><hr><h2 id="_3-2-集群架构" tabindex="-1">3.2 集群架构 <a class="header-anchor" href="#_3-2-集群架构" aria-label="Permalink to &quot;3.2 集群架构&quot;">​</a></h2><p>集群由多个「主节点 + 从节点」组成，每个主节点负责一部分槽，从节点作为主节点的副本。</p><p><img src="`+s+`" alt="Redis Cluster 分片架构"></p><p>节点之间通过 <strong>Gossip 协议</strong>互相通信，交换集群状态、槽分配、节点健康信息。</p><hr><h2 id="_3-3-moved-与-ask-重定向" tabindex="-1">3.3 MOVED 与 ASK 重定向 <a class="header-anchor" href="#_3-3-moved-与-ask-重定向" aria-label="Permalink to &quot;3.3 MOVED 与 ASK 重定向&quot;">​</a></h2><p>当客户端请求的 key 不在当前节点时，节点会返回重定向响应。</p><h3 id="moved-永久重定向" tabindex="-1">MOVED（永久重定向） <a class="header-anchor" href="#moved-永久重定向" aria-label="Permalink to &quot;MOVED（永久重定向）&quot;">​</a></h3><p>节点计算出 key 属于其他节点时，返回 <code>MOVED</code> 错误，告诉客户端去正确的节点：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 → 节点A：GET user:1001</span></span>
<span class="line"><span>节点A  → 客户端：-MOVED 12345 节点B的地址   （key 在节点 B）</span></span>
<span class="line"><span>客户端 → 节点B：GET user:1001（重新请求）</span></span></code></pre></div><p><code>MOVED</code> 是永久重定向，智能客户端会缓存槽与节点的映射，下次直接请求正确节点。</p><h3 id="ask-临时重定向" tabindex="-1">ASK（临时重定向） <a class="header-anchor" href="#ask-临时重定向" aria-label="Permalink to &quot;ASK（临时重定向）&quot;">​</a></h3><p>集群扩容/缩容、槽迁移期间，key 可能正在从旧节点迁往新节点，此时返回 <code>ASK</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 → 节点A：GET user:1001</span></span>
<span class="line"><span>节点A  → 客户端：-ASK 12345 节点B的地址   （槽正在迁移）</span></span>
<span class="line"><span>客户端 → 节点B：ASKING + GET user:1001   （临时访问迁移中的 key）</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">类型</th><th style="text-align:left;">场景</th><th style="text-align:left;">客户端行为</th></tr></thead><tbody><tr><td style="text-align:left;">MOVED</td><td style="text-align:left;">槽已归属其他节点</td><td style="text-align:left;">更新本地映射，永久改道</td></tr><tr><td style="text-align:left;">ASK</td><td style="text-align:left;">槽正在迁移</td><td style="text-align:left;">临时访问一次，不更新映射</td></tr></tbody></table><hr><h2 id="_3-4-跨槽与哈希标签" tabindex="-1">3.4 跨槽与哈希标签 <a class="header-anchor" href="#_3-4-跨槽与哈希标签" aria-label="Permalink to &quot;3.4 跨槽与哈希标签&quot;">​</a></h2><h3 id="跨槽问题" tabindex="-1">跨槽问题 <a class="header-anchor" href="#跨槽问题" aria-label="Permalink to &quot;跨槽问题&quot;">​</a></h3><p>集群下，多 key 命令（如 <code>MGET</code>、事务、Lua）要求所有 key 在同一个槽，否则报错。因为不同 key 可能分散在不同节点，无法保证原子性。</p><h3 id="哈希标签" tabindex="-1">哈希标签 <a class="header-anchor" href="#哈希标签" aria-label="Permalink to &quot;哈希标签&quot;">​</a></h3><p>哈希标签（hash tag）强制多个 key 落到同一个槽——只对 <code>{}</code> 内的内容计算哈希：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{user:1001}:name   → 只对 &quot;user:1001&quot; 计算槽</span></span>
<span class="line"><span>{user:1001}:age    → 只对 &quot;user:1001&quot; 计算槽</span></span>
<span class="line"><span>两者槽号相同，可用 MGET 一起操作</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MGET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {user:1001}:name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {user:1001}:age</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 合法，同一槽</span></span></code></pre></div><p>要点：</p><table tabindex="0"><thead><tr><th style="text-align:left;">要点</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">哈希标签</td><td style="text-align:left;"><code>{}</code> 内的内容决定槽号</td></tr><tr><td style="text-align:left;">强制同槽</td><td style="text-align:left;">相关 key 用相同 hash tag 保证同槽</td></tr><tr><td style="text-align:left;">副作用</td><td style="text-align:left;">过度使用会导致数据倾斜</td></tr></tbody></table><hr><h2 id="_3-5-三种方案选型" tabindex="-1">3.5 三种方案选型 <a class="header-anchor" href="#_3-5-三种方案选型" aria-label="Permalink to &quot;3.5 三种方案选型&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">主从</th><th style="text-align:left;">哨兵</th><th style="text-align:left;">集群</th></tr></thead><tbody><tr><td style="text-align:left;">数据分片</td><td style="text-align:left;">否</td><td style="text-align:left;">否</td><td style="text-align:left;">是</td></tr><tr><td style="text-align:left;">自动故障转移</td><td style="text-align:left;">否</td><td style="text-align:left;">是</td><td style="text-align:left;">是</td></tr><tr><td style="text-align:left;">水平扩展</td><td style="text-align:left;">否</td><td style="text-align:left;">否</td><td style="text-align:left;">是</td></tr><tr><td style="text-align:left;">读写分离</td><td style="text-align:left;">是</td><td style="text-align:left;">是</td><td style="text-align:left;">支持（从节点读）</td></tr><tr><td style="text-align:left;">实现复杂度</td><td style="text-align:left;">低</td><td style="text-align:left;">中</td><td style="text-align:left;">高</td></tr></tbody></table><p>选型建议：</p><table tabindex="0"><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">推荐方案</th></tr></thead><tbody><tr><td style="text-align:left;">数据量小、单机可装下、可接受手动切换</td><td style="text-align:left;">主从</td></tr><tr><td style="text-align:left;">数据量小、要求高可用</td><td style="text-align:left;">哨兵</td></tr><tr><td style="text-align:left;">数据量大、需要水平扩展</td><td style="text-align:left;">集群</td></tr></tbody></table>`,43)])])}const y=e(I,[["render",d]]);export{p as __pageData,y as default};
